package com.hpe.morpheus.harvester.plugin.apihelper

import com.hpe.morpheus.harvester.plugin.utils.HarvesterConstants
import com.morpheusdata.model.ComputeServerGroup
import com.morpheusdata.response.ServiceResponse
import groovy.util.logging.Slf4j

/**
 * Helper class for Harvester PVC API operations
 * Purpose: Provides high-level API methods for Harvester Persistent Volume Claim operations
 * Author: Generated by GitHub Copilot
 * Date: August 19, 2025
 */
@Slf4j
class PVCApiHelper {
    // Instance fields for configuration
    private ComputeServerGroup serverGroup
    private HarvesterApiClient apiClient

    /**
     * Create instance with ComputeServerGroup credentials
     * @param serverGroup ComputeServerGroup containing credentials
     */
    PVCApiHelper(ComputeServerGroup serverGroup = null) {
        this.serverGroup = serverGroup
        this.apiClient = new HarvesterApiClient(serverGroup)
        log.debug "Initialized PVCApiHelper with authentication"
    }

    /**
     * Fetch PVCs from Harvester API and cache them
     * @param token The API token
     * @return Map of PVC details keyed by claimName
     */
    def getPVCs(Boolean namespacePVCMap = false) {
        def ret = [success: true, pvcs: [], namespacePVCMap: [:]]

        try {
            ServiceResponse pvcsResponse = apiClient.get(HarvesterConstants.HARVESTER_API_V1_PVCS)

            if (pvcsResponse.success) {
                def pvcs = pvcsResponse.data?.items ?: []

                pvcs.each { pvc ->
                    String pvcName = pvc.metadata.name
                    String pvcNamespace = pvc.metadata.namespace

                    // Filter out system namespaces
                    if (!CommonApiHelper.isSystemNamespace(pvcNamespace)) {
                        def storageClass = pvc.spec?.storageClassName
                        def requestedStorage = pvc.spec?.resources?.requests?.storage
                        def sizeBytes = requestedStorage ? VirtualMachineApiHelper.parseVolumeSize(requestedStorage) : 0L

                        def pvcDetails = [
                            uid:  pvc.metadata.uid,
                            name: pvcName,
                            namespace: pvcNamespace,
                            storageClass: storageClass,
                            sizeBytes: sizeBytes,
                            status: pvc.status?.phase ?: 'Unknown',
                            ownerReferences: pvc.metadata?.ownerReferences,
                            dataSource: pvc.spec?.dataSource
                        ]

                        // Key by namespace:name for unique identification
                        if (namespacePVCMap) {
                            String pvcKey = "${pvcNamespace}:${pvcName}"
                            ret.namespacePVCMap[pvcKey] = pvcDetails
                        } else{
                            ret.pvcs << pvcDetails
                        }
                    }
                }
                ret.success = true
            } else {
                log.error("Failed to fetch PVCs from Harvester: ${pvcsResponse.msg}, errorCode:${pvcsResponse.errorCode}")
                ret.success = false
                ret.message = pvcsResponse.msg ?: 'Failed to fetch PVCs from Harvester'
            }
        } catch (Exception e) {
            log.error("Error fetching PVCs from Harvester", e)
            ret.success = false
            ret.message = "Error fetching PVCs: ${e.message}"
        }
        return ret
    }
}
